    // Use InstancedMesh for performance if many trails active
  }
}
```

#### Shockwave System (`ShockwaveSystem.js`)
```javascript
class ShockwaveSystem {
  constructor() {
    this.shockwaves = [];
    this.geometry = new THREE.TorusGeometry(1, 0.2, 8, 64);
    this.material = new MeshStandardMaterial({
      color: 0xffffff,
      emissive: 0x00ffff,
      emissiveIntensity: 3,
      transparent: true,
      opacity: 1,
      side: THREE.DoubleSide
    });
  }

  spawn(position) {
    const mesh = new THREE.Mesh(this.geometry, this.material);
    mesh.position.copy(position);
    mesh.scale.set(0.1, 0.1, 0.1);
    mesh.userData = { 
      maxScale: 3, 
      lifetime: 0.5, // seconds
      birthTime: performance.now() / 1000
    };
    scene.add(mesh);
    this.shockwaves.push(mesh);
  }

  update(deltaTime) {
    const now = performance.now() / 1000;
    this.shockwaves.forEach(sw => {
      const age = now - sw.userData.birthTime;
      const progress = age / sw.userData.lifetime;

      // Scale up, fade out
      sw.scale.setScalar(progress * sw.userData.maxScale);
      sw.material.opacity = 1 - progress;
    });

    // Remove expired shockwaves
    this.shockwaves = this.shockwaves.filter(sw => {
      if (now - sw.userData.birthTime >= sw.userData.lifetime) {
        scene.remove(sw);
        return false;
      }
      return true;
    });
  }
}
```

#### Floating Text (`FloatingText3D.js`)
```javascript
class FloatingText3D {
  constructor(uiContainer) {
    this.elements = [];
    this.uiContainer = uiContainer; // HTML container for overlays
  }

  spawn(text, worldPosition, color = '#00ff88') {
    const el = document.createElement('div');
    el.className = 'floating-text';
    el.textContent = text;
    el.style.color = color;
    el.style.textShadow = `0 0 10px ${color}`;

    // Convert world position to screen coordinates
    const vector = worldPosition.clone().project(camera);
    const x = (vector.x * 0.5 + 0.5) * window.innerWidth;
    const y = (-vector.y * 0.5 + 0.5) * window.innerHeight;

    el.style.left = `${x}px`;
    el.style.top = `${y}px`;

    this.uiContainer.appendChild(el);
    this.elements.push({ element: el, birthTime: performance.now() });

    // Auto-remove after animation completes
    setTimeout(() => {
      el.remove();
      this.elements = this.elements.filter(e => e.element !== el);
    }, 1000);
  }
}
```

