import { SpaceInvadersGame } from './SpaceInvadersGame.js';

// Initialize and start the game when DOM is ready
async function main() {
  const game = new SpaceInvadersGame();

  try {
    await game.init();
    console.log('Space Invaders initialized successfully');
    game.start();
  } catch (error) {
    console.error('Failed to initialize game:', error);
    document.getElementById('ui-overlay').innerHTML = `
      <div class="glass-panel error-panel">
        <h1>Initialization Failed</h1>
        <p>${error.message}</p>
        <button onclick="location.reload()">Retry</button>
      </div>
    `;
  }
}

// Wait for DOM ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', main);
} else {
  main();
}

