import * as THREE from 'three';
import { CONFIG } from '../config.js';
import { createInvaderGeometry, createInvaderMaterial } from '../../shared/procedural/GeometryGenerator.js';

export class Invader {
  constructor(type, row, col, gridX, gridY) {
    this.type = type; // 'squid', 'crab', or 'octopus'
    this.row = row;
    this.col = col;

    // Position within the grid formation
    this.localX = 0;
    this.localY = 0;

    // Calculate initial position based on grid layout
    const spacingX = CONFIG.invaderSpacingX;
    const spacingY = CONFIG.invaderSpacingY;
    const centerX = (CONFIG.screenWidth - (CONFIG.invaderCols * spacingX)) / 2;
    this.localX = col * spacingX + centerX;
    this.localY = gridY - row * spacingY;

    // Mesh creation
    this.geometry = createInvaderGeometry(type);
    this.material = createInvaderMaterial(type, CONFIG.colors[type]);
    this.mesh = new THREE.Mesh(this.geometry, this.material);
    this.mesh.position.set(this.localX, this.localY, 0);
    this.mesh.scale.set(1.5, 1.5, 1.5);

    // Animation state
    this.animationFrame = 0;
    this.animationTimer = 0;
    this.isAlive = true;

    // Hit squash effect
    this.targetScaleX = 1.5;
    this.targetScaleY = 1.5;
    this.currentScaleX = 1.5;
    this.currentScaleY = 1.5;
    this.squashTimer = 0;

    // Value for scoring
    this.points = CONFIG.points[type];
  }

  update(deltaTime, gridOffset) {
    if (!this.isAlive) return;

    // Animation timer
    this.animationTimer += deltaTime;
    if (this.animationTimer >= CONFIG.invaderAnimationInterval) {
      this.animationTimer = 0;
      this.animationFrame = 1 - this.animationFrame;
      // Flip texture or geometry based on frame
      this.mesh.rotation.z = this.animationFrame === 0 ? 0 : Math.PI * 0.1;
    }

    // Squash recovery animation
    if (this.squashTimer > 0) {
      this.squashTimer -= deltaTime;
      const progress = 1 - (this.squashTimer / 0.1);
      this.currentScaleX = THREE.MathUtils.lerp(this.targetScaleX * 1.3, this.targetScaleX, progress);
      this.currentScaleY = THREE.MathUtils.lerp(this.targetScaleY * 0.7, this.targetScaleY, progress);
    } else {
      this.currentScaleX = this.targetScaleX;
      this.currentScaleY = this.targetScaleY;
    }

    // Apply squash scale smoothly
    this.mesh.scale.set(
      THREE.MathUtils.lerp(this.mesh.scale.x, this.currentScaleX, 0.2),
      THREE.MathUtils.lerp(this.mesh.scale.y, this.currentScaleY, 0.2),
      this.mesh.scale.z
    );

    // Update world position with grid offset
    this.mesh.position.x = this.localX + gridOffset;
    this.mesh.position.y = this.localY;

    // Return hitbox for collision detection
    return {
      x: this.mesh.position.x,
      y: this.mesh.position.y,
      width: CONFIG.invaderWidth * this.currentScaleX,
      height: CONFIG.invaderHeight * this.currentScaleY,
      invader: this
    };
  }

  squash() {
    // Trigger squash animation for visual feedback
    this.squashTimer = 0.1;
    this.targetScaleX *= 1.3;
    this.targetScaleY *= 0.7;
  }

  die() {
    this.isAlive = false;
    return {
      position: new THREE.Vector3(
        this.mesh.position.x,
        this.mesh.position.y,
        0
      ),
      color: CONFIG.colors[this.type],
      points: this.points,
      type: this.type
    };
  }

  dispose() {
    if (this.geometry) this.geometry.dispose();
    if (this.material) this.material.dispose();
  }
}

export class InvaderGrid {
  constructor(scene) {
    this.scene = scene;
    this.invaders = [];
    this.gridOffsetX = 0;
    this.gridDirection = 1; // 1 = right, -1 = left

    // Movement state
    this.baseSpeed = CONFIG.baseGridSpeed;
    this.currentSpeed = this.baseSpeed;
    this.moveTimer = 0;

    // Formation dimensions
    this.rows = CONFIG.invaderRows;
    this.cols = CONFIG.invaderCols;

    // Track which invaders are alive per column for shooting logic
    this.alivePerColumn = [];

    // Initialize the grid
    this.createGrid();
  }

  createGrid() {
    const typeOrder = ['squid', 'crab', 'octopus', 'octopus', 'octopus'];
    const startY = CONFIG.invaderStartY;

    for (let row = 0; row < this.rows; row++) {
      for (let col = 0; col < this.cols; col++) {
        const type = typeOrder[row];
        const invader = new Invader(type, row, col, 0, startY);
        this.invaders.push(invader);
        this.scene.add(invader.mesh);
      }
    }

    // Initialize alive tracking per column
    for (let col = 0; col < this.cols; col++) {
      this.alivePerColumn[col] = [];
      for (let row = 0; row < this.rows; row++) {
        const invader = this.invaders[row * this.cols + col];
        if (invader.isAlive) {
          this.alivePerColumn[col].push(invader);
        }
      }
    }

    // Calculate initial bounds
    this.leftBound = CONFIG.screenWidth / 2 - (this.cols * CONFIG.invaderSpacingX) / 2;
    this.rightBound = CONFIG.screenWidth / 2 + (this.cols * CONFIG.invaderSpacingX) / 2;
  }

  update(deltaTime, playerY) {
    // Calculate speed based on remaining invaders
    const aliveCount = this.getAliveCount();
    if (aliveCount === 0) return null;

    // Speed increases as invaders die
    const initialCount = this.rows * this.cols;
    const speedMultiplier = 1 + (initialCount - aliveCount) / initialCount * CONFIG.speedBoostFactor;
    this.currentSpeed = this.baseSpeed * speedMultiplier;

    // Move the grid
    this.moveTimer += deltaTime;
    const moveAmount = this.currentSpeed * deltaTime * this.gridDirection;
    this.gridOffsetX += moveAmount;

    // Check bounds and step down if needed
    const currentLeft = this.leftBound + this.gridOffsetX;
    const currentRight = this.rightBound + this.gridOffsetX;
    const screenLeft = -CONFIG.screenWidth / 2 + CONFIG.borderPadding;
    const screenRight = CONFIG.screenWidth / 2 - CONFIG.borderPadding;

    if (currentLeft < screenLeft || currentRight > screenRight) {
      // Step down and reverse direction
      this.gridDirection *= -1;
      const stepDownAmount = CONFIG.stepDownAmount;

      // Move all invaders down
      for (const invader of this.invaders) {
        if (invader.isAlive) {
          invader.localY -= stepDownAmount;
        }
      }

      // Check if invaders reached the floor (game over condition)
      const lowestInvader = Math.max(...this.invaders.filter(i => i.isAlive).map(i => i.localY));
      if (lowestInvader >= playerY - CONFIG.gameOverThreshold) {
        return { gameOver: true, reason: 'invaders_reached_floor' };
      }
    }

    // Update all invaders and collect hitboxes
    const hitboxes = [];
    for (const invader of this.invaders) {
      if (invader.isAlive) {
        const hitbox = invader.update(deltaTime, this.gridOffsetX);
        if (hitbox) hitboxes.push(hitbox);
      }
    }

    return { hitboxes, aliveCount };
  }

  getShooterForColumn(colIndex) {
    // Get the bottom-most alive invader in a column
    const columnInvaders = this.alivePerColumn[colIndex] || [];
    if (columnInvaders.length === 0) return null;

    // Sort by Y position (highest first, which is lowest on screen)
    columnInvaders.sort((a, b) => b.localY - a.localY);
    return columnInvaders[0];
  }

  getAliveCount() {
    return this.invaders.filter(i => i.isAlive).length;
  }

  isAllDead() {
    return this.getAliveCount() === 0;
  }

  reset(gridOffsetX = 0) {
    // Remove old invaders from scene
    for (const invader of this.invaders) {
      if (invader.mesh.parent) {
        this.scene.remove(invader.mesh);
      }
      invader.dispose();
    }

    this.invaders = [];
    this.gridOffsetX = gridOffsetX;
    this.createGrid();
  }

  dispose() {
    for (const invader of this.invaders) {
      if (invader.mesh.parent) {
        this.scene.remove(invader.mesh);
      }
      invader.dispose();
    }
    this.invaders = [];
  }
}

import * as THREE from 'three';

/**
 * Procedural Geometry Generator for Space Invaders
 * All geometries are created via Three.js primitives and ExtrudeGeometry
 */

/**
 * Create player ship geometry - sleek angular fighter shape
 */
export function createPlayerShipGeometry() {
  const shape = new THREE.Shape();

  // Main body - triangular with pointed nose
  shape.moveTo(0, -12);
  shape.lineTo(8, 4);
  shape.lineTo(5, 6);
  shape.lineTo(-5, 6);
  shape.lineTo(-8, 4);
  shape.closePath();

  // Engine detail (hole)
  const engineHole = new THREE.Path();
  engineHole.absarc(0, -2, 3, Math.PI, 0, false);
  shape.holes.push(engineHole);

  const extrudeSettings = {
    depth: 2,
    bevelEnabled: true,
    bevelThickness: 0.5,
    bevelSize: 0.5,
    bevelSegments: 2
  };

  return new THREE.ExtrudeGeometry(shape, extrudeSettings);
}

/**
 * Create invader geometry based on type
 * @param {'squid' | 'crab' | 'octopus'} type 
 */
export function createInvaderGeometry(type) {
  let shape;

  switch (type) {
    case 'squid':
      // Triangular body with legs - top row, most valuable
      shape = new THREE.Shape();
      shape.moveTo(0, -8);
      shape.lineTo(6, -4);
      shape.lineTo(4, 0);
      shape.lineTo(2, 4);
      shape.lineTo(-2, 4);
      shape.lineTo(-4, 0);
      shape.lineTo(-6, -4);
      shape.closePath();

      // Eye holes
      const leftEye = new THREE.Path();
      leftEye.absarc(-2.5, -1, 1, 0, Math.PI * 2, false);
      const rightEye = new THREE.Path();
      rightEye.absarc(2.5, -1, 1, 0, Math.PI * 2, false);
      shape.holes.push(leftEye);
      shape.holes.push(rightEye);
      break;

    case 'crab':
      // Wide body with claws - middle rows
      shape = new THREE.Shape();
      shape.moveTo(-8, -4);
      shape.lineTo(8, -4);
      shape.lineTo(10, 0);
      shape.lineTo(6, 4);
      shape.lineTo(-6, 4);
      shape.lineTo(-10, 0);
      shape.closePath();

      // Central body detail
      const bodyHole = new THREE.Path();
      bodyHole.absarc(0, 0, 3, 0, Math.PI * 2, false);
      shape.holes.push(bodyHole);
      break;

    case 'octopus':
      // Rounded with tentacles - bottom rows, most common
      shape = new THREE.Shape();
      shape.moveTo(0, -6);
      shape.lineTo(7, -2);
      shape.lineTo(8, 2);
      shape.lineTo(4, 5);
      shape.lineTo(-4, 5);
      shape.lineTo(-8, 2);
      shape.lineTo(-7, -2);
      shape.closePath();

      // Tentacle notches (simplified as holes)
      const tent1 = new THREE.Path();
      tent1.absarc(-3, 0, 1.5, Math.PI, 0, false);
      const tent2 = new THREE.Path();
      tent2.absarc(3, 0, 1.5, Math.PI, 0, false);
      shape.holes.push(tent1);
      shape.holes.push(tent2);
      break;

    default:
      // Fallback simple box
      return new THREE.BoxGeometry(8, 8, 2);
  }

  const extrudeSettings = {
    depth: 1.5,
    bevelEnabled: true,
    bevelThickness: 0.3,
    bevelSize: 0.3,
    bevelSegments: 1
  };

  return new THREE.ExtrudeGeometry(shape, extrudeSettings);
}

/**
 * Create bullet geometry - elongated cylinder with glow tip
 */
export function createBulletGeometry() {
  const geometry = new THREE.CylinderGeometry(0.4, 0.4, 6, 8);
  geometry.rotateX(Math.PI / 2); // Point along Z axis initially

  return geometry;
}

/**
 * Create enemy bullet geometry - larger, more menacing
 */
export function createEnemyBulletGeometry() {
  const geometry = new THREE.ConeGeometry(0.6, 4, 8);
  geometry.rotateX(-Math.PI / 2); // Point downward

  return geometry;
}

/**
 * Create explosion particle geometry - small tetrahedron for variety
 */
export function createParticleGeometry() {
  const geometries = [
    new THREE.BoxGeometry(0.3, 0.3, 0.3),
    new THREE.OctahedronGeometry(0.25),
    new THREE.DodecahedronGeometry(0.2)
  ];

  // Return array for variety in particle system
  return geometries;
}

/**
 * Create shockwave ring geometry - torus with high segment count
 */
export function createShockwaveGeometry() {
  return new THREE.TorusGeometry(1, 0.25, 8, 64);
}

/**
 * Create starfield geometry - many small points at various depths
 * Returns array of Mesh objects for immediate use
 */
export function createStarfield(scene, count = 200) {
  const stars = [];
  const starGeometry = new THREE.BoxGeometry(0.3, 0.3, 0.3);

  for (let i = 0; i < count; i++) {
    const material = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      emissive: 0x444444,
      emissiveIntensity: 0.5
    });

    const star = new THREE.Mesh(starGeometry, material);

    // Random position in 3D space behind gameplay area
    star.position.set(
      (Math.random() - 0.5) * 1200,
      (Math.random() - 0.5) * 800,
      -50 - Math.random() * 200 // Behind main scene
    );

    // Random scale for depth effect
    const scale = 0.3 + Math.random() * 0.7;
    star.scale.setScalar(scale);

    // Store parallax speed based on Z position (further = slower)
    star.userData.parallaxSpeed = 1 - (star.position.z + 50) / 200;

    scene.add(star);
    stars.push(star);
  }

  return stars;
}

/**
 * Create mothership geometry - large boss entity
 */
export function createMothershipGeometry() {
  const shape = new THREE.Shape();

  // Main saucer body
  shape.moveTo(0, -15);
  shape.lineTo(25, -8);
  shape.lineTo(35, 0);
  shape.lineTo(25, 8);
  shape.lineTo(-25, 8);
  shape.lineTo(-35, 0);
  shape.lineTo(-25, -8);
  shape.closePath();

  // Cockpit dome (hole)
  const cockpit = new THREE.Path();
  cockpit.absarc(0, 0, 8, 0, Math.PI * 2, false);
  shape.holes.push(cockpit);

  const extrudeSettings = {
    depth: 4,
    bevelEnabled: true,
    bevelThickness: 1,
    bevelSize: 1,
    bevelSegments: 3
  };

  return new THREE.ExtrudeGeometry(shape, extrudeSettings);
}

/**
 * Create grid background geometry - retro scanline effect
 */
export function createGridBackground(width = 800, height = 600) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');

  // Dark background
  ctx.fillStyle = '#0a0a1a';
  ctx.fillRect(0, 0, width, height);

  // Horizontal scanlines
  ctx.strokeStyle = 'rgba(0, 255, 255, 0.03)';
  ctx.lineWidth = 1;

  for (let y = 0; y < height; y += 4) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(width, y);
    ctx.stroke();
  }

  // Vertical grid lines (fainter)
  ctx.strokeStyle = 'rgba(255, 0, 255, 0.02)';

  for (let x = 0; x < width; x += 40) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, height);
    ctx.stroke();
  }

  // Create texture from canvas
  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.ClampToEdgeWrapping;
  texture.wrapT = THREE.ClampToEdgeWrapping;

  return texture;
}

/**
 * Pre-create and cache geometries for performance
 */
export class GeometryCache {
  constructor() {
    this.cached = new Map();
  }

  get(key, createFn) {
    if (!this.cached.has(key)) {
      this.cached.set(key, createFn());
    }
    return this.cached.get(key);
  }

  clear() {
    for (const [key, geom] of this.cached.entries()) {
      geom.dispose();
    }
    this.cached.clear();
  }
}

// Export a shared cache instance
export const geometryCache = new GeometryCache();

import * as THREE from 'three';

/**
 * Procedural texture generation using Canvas API
 * Zero external assets - all textures generated at runtime
 */

export function generateInvaderSprite(type, size = 64) {
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');

  // Color mapping by invader type
  const colors = {
    squid: '#ff00ff',   // Magenta
    crab: '#ffff00',     // Yellow
    octopus: '#00ff00'   // Green
  };

  const color = colors[type] || '#ffffff';
  ctx.fillStyle = color;

  const halfW = size / 2;
  const halfH = size / 2;

  if (type === 'squid') {
    // Squid: triangular body with legs at bottom
    ctx.beginPath();
    // Main body - triangle pointing down
    ctx.moveTo(halfW, 8);
    ctx.lineTo(halfW + 16, halfH);
    ctx.lineTo(halfW - 16, halfH);
    ctx.closePath();

    // Eyes
    ctx.fillRect(halfW - 8, halfH - 4, 4, 4);
    ctx.fillRect(halfW + 4, halfH - 4, 4, 4);

    // Legs at bottom
    for (let i = 0; i < 5; i++) {
      const legX = halfW - 12 + i * 6;
      ctx.fillRect(legX, halfH + 4, 3, 8);
    }

    // Arms on sides
    ctx.fillRect(halfW - 20, halfH - 4, 4, 4);
    ctx.fillRect(halfW + 16, halfH - 4, 4, 4);

  } else if (type === 'crab') {
    // Crab: wider body with claws
    ctx.beginPath();
    // Main body - rounded rectangle
    ctx.rect(8, 12, size - 16, halfH - 8);

    // Top protrusions
    ctx.fillRect(halfW - 4, 8, 8, 8);
    ctx.fillRect(12, 8, 6, 8);
    ctx.fillRect(size - 18, 8, 6, 8);

    // Eyes on stalks
    ctx.fillStyle = '#000';
    ctx.beginPath();
    ctx.arc(halfW - 10, 24, 3, 0, Math.PI * 2);
    ctx.arc(halfW + 10, 24, 3, 0, Math.PI * 2);
    ctx.fill();

    // Claws on sides
    ctx.fillStyle = color;
    ctx.fillRect(4, halfH - 8, 6, 8);
    ctx.fillRect(size - 10, halfH - 8, 6, 8);

    // Legs at bottom
    for (let i = 0; i < 4; i++) {
      const legX = 12 + i * 14;
      ctx.fillRect(legX, halfH + 4, 4, 8);
    }

  } else if (type === 'octopus') {
    // Octopus: rounded body with tentacles
    ctx.beginPath();
    // Main body - oval
    ctx.ellipse(halfW, halfH - 4, 16, 12, 0, 0, Math.PI * 2);

    // Eyes
    ctx.fillStyle = '#000';
    ctx.beginPath();
    ctx.arc(halfW - 8, halfH - 6, 3, 0, Math.PI * 2);
    ctx.arc(halfW + 8, halfH - 6, 3, 0, Math.PI * 2);
    ctx.fill();

    // Tentacles at bottom
    ctx.fillStyle = color;
    for (let i = 0; i < 4; i++) {
      const tentacleX = halfW - 12 + i * 8;
      ctx.beginPath();
      ctx.moveTo(tentacleX, halfH + 6);
      ctx.lineTo(tentacleX + 2, halfH + 14);
      ctx.lineTo(tentacleX + 4, halfH + 6);
      ctx.closePath();
    }

    // Side arms
    ctx.fillRect(8, halfH - 2, 8, 4);
    ctx.fillRect(size - 16, halfH - 2, 8, 4);
  }

  // Create texture with transparency
  const texture = new THREE.CanvasTexture(canvas);
  texture.magFilter = THREE.NearestFilter;
  texture.minFilter = THREE.NearestFilter;

  return texture;
}

export function generateStarfield(width, height) {
  const canvas = document.createElement('canvas');
  canvas.width = width || 1024;
  canvas.height = height || 1024;
  const ctx = canvas.getContext('2d');

  // Dark space background
  ctx.fillStyle = '#0a0a1a';
  ctx.fillRect(0, 0, width, height);

  // Generate stars at different brightness levels
  const starCount = Math.floor(width * height / 500);

  for (let i = 0; i < starCount; i++) {
    const x = Math.random() * width;
    const y = Math.random() * height;
    const size = Math.random() * 2 + 0.5;
    const brightness = Math.random();

    ctx.fillStyle = `rgba(255, 255, 255, ${brightness})`;
    ctx.beginPath();
    ctx.arc(x, y, size, 0, Math.PI * 2);
    ctx.fill();

    // Add glow to brighter stars
    if (brightness > 0.7) {
      const gradient = ctx.createRadialGradient(x, y, 0, x, y, size * 3);
      gradient.addColorStop(0, `rgba(255, 255, 255, ${brightness * 0.3})`);
      gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');
      ctx.fillStyle = gradient;
      ctx.beginPath();
      ctx.arc(x, y, size * 3, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;

  return texture;
}

export function generateGridBackground(width, height) {
  const canvas = document.createElement('canvas');
  canvas.width = width || 512;
  canvas.height = height || 512;
  const ctx = canvas.getContext('2d');

  // Deep space gradient background
  const bgGradient = ctx.createLinearGradient(0, 0, 0, height);
  bgGradient.addColorStop(0, '#0a0a20');
  bgGradient.addColorStop(0.5, '#101030');
  bgGradient.addColorStop(1, '#0a0a20');
  ctx.fillStyle = bgGradient;
  ctx.fillRect(0, 0, width, height);

  // Retro grid lines (subtle)
  ctx.strokeStyle = 'rgba(0, 255, 255, 0.03)';
  ctx.lineWidth = 1;

  const gridSize = 32;
  for (let x = 0; x < width; x += gridSize) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, height);
    ctx.stroke();
  }

  for (let y = 0; y < height; y += gridSize) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(width, y);
    ctx.stroke();
  }

  // Vignette effect
  const vignetteGradient = ctx.createRadialGradient(
    width / 2, height / 2, height * 0.3,
    width / 2, height / 2, height * 0.8
  );
  vignetteGradient.addColorStop(0, 'rgba(0, 0, 0, 0)');
  vignetteGradient.addColorStop(1, 'rgba(0, 0, 0, 0.4)');
  ctx.fillStyle = vignetteGradient;
  ctx.fillRect(0, 0, width, height);

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.ClampToEdgeWrapping;

  return texture;
}

