    const startY = CONFIG.invaderStartY;

    for (let row = 0; row < this.rows; row++) {
      for (let col = 0; col < this.cols; col++) {
        const type = typeOrder[row];
        const invader = new Invader(type, row, col, 0, startY);
        this.invaders.push(invader);
        this.scene.add(invader.mesh);
      }
    }

    // Initialize alive tracking per column
    for (let col = 0; col < this.cols; col++) {
      this.alivePerColumn[col] = [];
      for (let row = 0; row < this.rows; row++) {
        const invader = this.invaders[row * this.cols + col];
        if (invader.isAlive) {
          this.alivePerColumn[col].push(invader);
        }
      }
    }

    // Calculate initial bounds
    this.leftBound = CONFIG.screenWidth / 2 - (this.cols * CONFIG.invaderSpacingX) / 2;
    this.rightBound = CONFIG.screenWidth / 2 + (this.cols * CONFIG.invaderSpacingX) / 2;
  }

  update(deltaTime, playerY) {
    // Calculate speed based on remaining invaders
    const aliveCount = this.getAliveCount();
    if (aliveCount === 0) return null;

    // Speed increases as invaders die
    const initialCount = this.rows * this.cols;
    const speedMultiplier = 1 + (initialCount - aliveCount) / initialCount * CONFIG.speedBoostFactor;
    this.currentSpeed = this.baseSpeed * speedMultiplier;

    // Move the grid
    this.moveTimer += deltaTime;
    const moveAmount = this.currentSpeed * deltaTime * this.gridDirection;
    this.gridOffsetX += moveAmount;

    // Check bounds and step down if needed
    const currentLeft = this.leftBound + this.gridOffsetX;
    const currentRight = this.rightBound + this.gridOffsetX;
    const screenLeft = -CONFIG.screenWidth / 2 + CONFIG.borderPadding;
    const screenRight = CONFIG.screenWidth / 2 - CONFIG.borderPadding;

    if (currentLeft < screenLeft || currentRight > screenRight) {
      // Step down and reverse direction
      this.gridDirection *= -1;
      const stepDownAmount = CONFIG.stepDownAmount;

      // Move all invaders down
      for (const invader of this.invaders) {
        if (invader.isAlive) {
          invader.localY -= stepDownAmount;
        }
      }

      // Check if invaders reached the floor (game over condition)
      const lowestInvader = Math.max(...this.invaders.filter(i => i.isAlive).map(i => i.localY));
      if (lowestInvader >= playerY - CONFIG.gameOverThreshold) {
        return { gameOver: true, reason: 'invaders_reached_floor' };
      }
    }

    // Update all invaders and collect hitboxes
    const hitboxes = [];
    for (const invader of this.invaders) {
      if (invader.isAlive) {
        const hitbox = invader.update(deltaTime, this.gridOffsetX);
        if (hitbox) hitboxes.push(hitbox);
      }
    }

    return { hitboxes, aliveCount };
  }

  getShooterForColumn(colIndex) {
    // Get the bottom-most alive invader in a column
    const columnInvaders = this.alivePerColumn[colIndex] || [];
    if (columnInvaders.length === 0) return null;

    // Sort by Y position (highest first, which is lowest on screen)
    columnInvaders.sort((a, b) => b.localY - a.localY);
    return columnInvaders[0];
  }

  getAliveCount() {
    return this.invaders.filter(i => i.isAlive).length;
  }

  isAllDead() {
    return this.getAliveCount() === 0;
  }

  reset(gridOffsetX = 0) {
    // Remove old invaders from scene
    for (const invader of this.invaders) {
      if (invader.mesh.parent) {
        this.scene.remove(invader.mesh);
      }
      invader.dispose();
    }

    this.invaders = [];
    this.gridOffsetX = gridOffsetX;
    this.createGrid();
  }

  dispose() {
    for (const invader of this.invaders) {
      if (invader.mesh.parent) {
        this.scene.remove(invader.mesh);
      }
      invader.dispose();
    }
    this.invaders = [];
  }
}

import * as THREE from 'three';
import { ObjectPool } from '../../shared/memory/ObjectPool.js';
import { Bullet } from '../entities/Bullet.js';

/**
 * ProjectileManager - Handles all bullets (player and enemy) with object pooling
 */
export class ProjectileManager {
  constructor(config) {
    this.config = config;

    // Player bullet pool (max 20 active at once)
    this.playerBulletPool = new ObjectPool(() => 
      new Bullet(
        config.bulletSpeed,
        'player',
        config.colors.bulletPlayer
      ),
      30
    );

    // Enemy bullet pool (max 50 active - invaders can fire frequently)
    this.enemyBulletPool = new ObjectPool(() => 
      new Bullet(
        config.enemyBulletSpeed,
        'enemy',
        config.colors.bulletEnemy
      ),
      100
    );

    // Active projectiles
    this.playerBullets = [];
    this.enemyBullets = [];

    // Bounds for cleanup
    this.bounds = {
      top: -50,
      bottom: 650,
      left: -50,
      right: 850
    };
  }

  /**
   * Spawn a player bullet at the given position
   */
  spawnPlayerBullet(position) {
    const bullet = this.playerBulletPool.acquire();
    bullet.reset(position.clone(), 1); // velocity y = 1 (upward)
    this.playerBullets.push(bullet);
    return bullet;
  }

  /**
   * Spawn an enemy bullet at the given position
   */
  spawnEnemyBullet(position) {
    const bullet = this.enemyBulletPool.acquire();
    bullet.reset(position.clone(), -1); // velocity y = -1 (downward)
    this.enemyBullets.push(bullet);
    return bullet;
  }

  /**
   * Update all projectiles and remove out-of-bounds ones
   */
  update(deltaTime, scene) {
    this.updateBulletGroup(this.playerBullets, this.playerBulletPool, scene);
    this.updateBulletGroup(this.enemyBullets, this.enemyBulletPool, scene);
  }

  /**
   * Update a group of bullets (player or enemy)
   */
  updateBulletGroup(bullets, pool, scene) {
    for (let i = bullets.length - 1; i >= 0; i--) {
      const bullet = bullets[i];

      // Move the bullet
      bullet.update(deltaTime);

      // Check if out of bounds
      if (this.isOutOfBounds(bullet)) {
        this.removeBullet(bullets, i, pool, scene);
      }
    }
  }

  /**
   * Check if a bullet is outside the playable area
   */
  isOutOfBounds(bullet) {
    const pos = bullet.getWorldPosition(new THREE.Vector3());

    // Player bullets go up (positive Y), enemy bullets go down (negative Y)
    if (bullet.isPlayerBullet()) {
      return pos.y > this.bounds.top;
    } else {
      return pos.y < this.bounds.bottom;
    }
  }

  /**
   * Remove a bullet from the array and return it to pool
   */
  removeBullet(bullets, index, pool, scene) {
    const bullet = bullets.splice(index, 1)[0];
    scene.remove(bullet.mesh);
    pool.release(bullet);
  }

  /**
   * Remove a specific bullet (used for collisions)
   */
  removePlayerBullet(bullet, scene) {
    const index = this.playerBullets.indexOf(bullet);
    if (index !== -1) {
      this.removeBullet(this.playerBullets, index, this.playerBulletPool, scene);
      return true;
    }
    return false;
  }

  removeEnemyBullet(bullet, scene) {
    const index = this.enemyBullets.indexOf(bullet);
    if (index !== -1) {
      this.removeBullet(this.enemyBullets, index, this.enemyBulletPool, scene);
      return true;
    }
    return false;
  }

  /**
   * Get all player bullets for collision checking
   */
  getPlayerBullets() {
    return this.playerBullets;
  }

  /**
   * Get all enemy bullets for collision checking
   */
  getEnemyBullets() {
    return this.enemyBullets;
  }

  /**
   * Clear all projectiles (used on game over / level reset)
   */
  clear(scene) {
    // Return all player bullets to pool
    while (this.playerBullets.length > 0) {
      const bullet = this.playerBullets.pop();
      scene.remove(bullet.mesh);
      this.playerBulletPool.release(bullet);
    }

    // Return all enemy bullets to pool
    while (this.enemyBullets.length > 0) {
      const bullet = this.enemyBullets.pop();
      scene.remove(bullet.mesh);
      this.enemyBulletPool.release(bullet);
    }
  }

  /**
   * Get count of active projectiles (for debugging)
   */
  getActiveCount() {
    return {
      player: this.playerBullets.length,
      enemy: this.enemyBullets.length,
      total: this.playerBullets.length + this.enemyBullets.length
    };
  }
}

